#!/usr/bin/env node
/**
 * Pre-commit: enforce migration DIRECTORY contract (真实安全不变量，不再依赖"自动生成标记")。
 *
 *   versions/ddl/  — 结构变更：禁止 op.execute()（数据操作请拆到 data/）
 *   versions/data/ — 数据迁移：docstring 须含 "# Manual override reason: data_only"
 *
 * 说明：迁移要么 alembic 自动生成、要么 AI/人手写，`# ### commands auto generated by Alembic`
 * 标记既非安全属性也无人阅读，故不再强制。安全由以下保证：
 *   - ddl/ 无数据操作（本检查）
 *   - data/ 声明意图（本检查）
 *   - 单一 head（CI + check-migration-chain.py）
 *   - 可逆性（pre-push alembic roundtrip base→head→base→head）
 * 仅检查本次“暂存”的迁移文件，不追溯既有已应用迁移。
 */
const { execSync } = require("node:child_process");
const { readFileSync } = require("node:fs");
const path = require("node:path");

const ROOT = execSync("git rev-parse --show-toplevel", { encoding: "utf-8" }).trim();
const DDL_DIR = path.join(ROOT, "backend", "migrations", "versions", "ddl");
const DATA_DIR = path.join(ROOT, "backend", "migrations", "versions", "data");

const staged = execSync(
  `git diff --cached --name-only --diff-filter=ACM -- "${DDL_DIR}/*.py" "${DATA_DIR}/*.py"`,
  { encoding: "utf-8" },
).trim();

if (!staged) process.exit(0);

const files = staged.split("\n").filter(Boolean);
const REASON_PREFIX = "# Manual override reason:";
const VALID_REASONS = ["data_only"];
const HAS_OP_EXECUTE = /^\s+op\.execute\(/m;

let errors = 0;

function report(file, error, fix) {
  errors++;
  console.error(
    [
      ``,
      `  ================================================================`,
      `  MIGRATION CHECK FAILED`,
      `  ================================================================`,
      `  File:  ${path.relative(ROOT, file)}`,
      `  Error: ${error}`,
      `  Fix:   ${fix}`,
      `  ================================================================`,
      ``,
    ].join("\n"),
  );
}

for (const f of files) {
  const content = readFileSync(f, "utf-8");
  const inDdl = f.startsWith(DDL_DIR);
  const inData = f.startsWith(DATA_DIR);

  if (inDdl && HAS_OP_EXECUTE.test(content)) {
    report(
      f,
      "DDL 迁移含 op.execute()（数据操作）",
      '移除 op.execute()，用 `pnpm run db:data "描述"` 新建 data/ 迁移承载数据操作。',
    );
  }

  if (inData) {
    const reasonLine = content.split("\n").find((l) => l.trimStart().startsWith(REASON_PREFIX));
    const reason = reasonLine?.split(":")[1]?.trim();
    if (!reason || !VALID_REASONS.includes(reason)) {
      report(f, '缺少 "# Manual override reason: data_only" 声明', "在模块 docstring 中加入该行。");
    }
  }
}

if (errors > 0) {
  console.error(`  ${errors} migration file(s) failed. See AGENTS.md § Migration Rules.\n`);
  process.exit(1);
}
